INSERT INTO analysis_rows (turn_id, element, finding, reconstructed) VALUES ('t1','Branches considered','(a) Long chat-only essay — rejected: evaporates, walls of prose; (b) one monolithic guide file — rejected: repo already has two, and monoliths defeat atomic retrieval; (c) interlinked atomic wiki pages + front-loaded chat summary — selected: the medium is the lesson',0);
INSERT INTO analysis_rows (turn_id, element, finding, reconstructed) VALUES ('t1','Pre-mortem','Failure 1: pages never read -> MOC entry point, README pointer, every page skimmable in 30s. Failure 2: duplicates existing repo guides -> pages link to them and position them as phase 2. Failure 3: ''train on my data'' misconception persists and misdirects the build -> the correction is the centerpiece of the layers page, with the user''s own analogy validated and relocated rather than dismissed',0);
INSERT INTO analysis_rows (turn_id, element, finding, reconstructed) VALUES ('t1','Grounding','Repo state, existing guides'' structure, and wiki protocol retrieved and read; Claude layer/product facts from model knowledge (early 2026), flagged as such in each page''s provenance section',0);
